const FSCHEMA = {"type": "object", "additionalProperties": false, "required": ["chapter", "findings"], "properties": {"chapter": {"type": "string"}, "findings": {"type": "array", "maxItems": 25, "items": {"type": "object", "additionalProperties": false, "required": ["category", "quote", "why_wrong", "fix", "confidence"], "properties": {"category": {"type": "string", "enum": ["math", "code", "numbers", "claims"]}, "quote": {"type": "string"}, "why_wrong": {"type": "string"}, "fix": {"type": "string"}, "confidence": {"type": "string", "enum": ["high", "medium", "low"]}}}}}};
const VSCHEMA = {"type": "object", "additionalProperties": false, "required": ["chapter", "confirmed_and_fixed", "rejected", "notes"], "properties": {"chapter": {"type": "string"}, "confirmed_and_fixed": {"type": "integer"}, "rejected": {"type": "integer"}, "fixes": {"type": "array", "items": {"type": "string"}}, "notes": {"type": "string"}}};
log('Red-teaming ' + JOBS.length + ' chapters (adversarial find -> skeptical verify+fix)…');
const results = await pipeline(
  JOBS,
  function (j) {
    return agent(j.find, { label: 'find:' + j.id, phase: 'Find', model: 'claude-opus-5', schema: FSCHEMA })
      .then(function (f) { return { j: j, findings: f }; })
      .catch(function (e) { return { j: j, findings: null }; });
  },
  async function (prev) {
    if (!prev || !prev.j) return null;
    const f = prev.findings;
    if (!f || !f.findings || f.findings.length === 0) return { id: prev.j.id, clean: true };
    const v = await agent(prev.j.fixv.replace('{FINDINGS}', JSON.stringify(f.findings).slice(0, 10000)),
      { label: 'fix:' + prev.j.id, phase: 'Verify+Fix', model: 'claude-opus-5', schema: VSCHEMA });
    return { id: prev.j.id, verdict: v };
  }
);
const done = results.filter(Boolean);
const fixed = done.reduce(function (s, r) { return s + (r.verdict ? (r.verdict.confirmed_and_fixed||0) : 0); }, 0);
log('Red-team r2b1: ' + done.length + '/' + JOBS.length + ' chapters, ' + fixed + ' confirmed bugs fixed.');
return { batch: 'r2b1', total: JOBS.length, done: done.length, bugs_fixed: fixed, results: results };
